content.content:
1	#!/usr/bin/env node
2	// The sheepdog pack's fleet-USAGE sweep — the third cross-repo reach the pack adds,
3	// alongside the coverage census and the freshness sweep. Run by this pack's
4	// `fleet-usage` scheduled task (tasks/fleet-usage/), whose worker calls `main()`
5	// below as the task's `prework`, Action-side inside the enforcer repo's
6	// scheduler workflow where FLEET_GITHUB_TOKEN is reachable. Still runnable by hand
7	// (`node aggregate-fleet-usage.mjs`) via the CLI guard at the foot.
8	//
9	// WHY IT EXISTS. Each member folds ITS OWN skill-usage aggregate (the
10	// grow_with_claudinite pack's usage-fold task). A member can therefore answer "does
11	// this skill ever load HERE" — and cannot answer the question the promotion ladder
12	// actually asks, which is whether a skill earns its place ACROSS THE FLEET. A skill
13	// that never loads in one repo may simply not be that repo's subject; a skill that
14	// never loads in any of them is mis-described or should not be gated at all. Only
15	// something looking at every member at once can tell those apart, and looking at
16	// every member is the sheepdog's whole job.
17	//
18	// STATELESS FULL RECOMPUTE. Read each member's usage file at its default branch and
19	// rebuild the fleet file as a pure function of those inputs. Idempotent by
20	// definition, and it self-heals any past error — at this cardinality (repos ×
21	// skills × weeks, all small) there is nothing to optimize away.
22	//
23	// COVERAGE IS EXPLICIT — over the WHOLE fleet, not just the members. A member with
24	// no usage file (not folding yet) or an unreadable one is LISTED as absent,
25	// census-style, never silently skipped. A denominator with an invisible hole in it
26	// is worse than no denominator. A member that declares itself DORMANT is out of the
27	// denominator entirely — and listed under its own heading, because "not in the
28	// race" and "should be folding and isn't" are different facts and only one of them
29	// is a problem. Uncovered and out-of-scope (archived/fork/excluded) repos are named
30	// too, contributing to no number: the coverage section accounts for every repo
31	// under the owner, so no state can drop a repo out of the report.
32	//
33	// The canon knows mechanisms, never repos: no member is named anywhere here. The
34	// member set is enumerated at runtime from the enforcer's own sheepdog config,
35	// exactly as the census and the freshness sweep enumerate it.
36	//
37	// Dependency-free (global fetch, Node 20+); read-only toward every member — the only
38	// thing it writes is the enforcer repo's own aggregate, and that is delivered by the
39	// worker, not here.
40	//
41	// It lives IN its task's folder because nothing else uses it. What IS shared with
42	// the other two sweeps sits at the pack root: the cross-repo REST primitives
43	// (fleet-api.mjs) and the config reader (fleet-config.mjs).
44	
45	import { pathToFileURL } from 'node:url';
46	import { makeGh, paged, readDeclaration, isDormant, DECLARATION } from '../../fleet-api.mjs';
47	import { parseSheepdogConfig } from '../../fleet-config.mjs';
48	export const MEMBER_USAGE_PATH = '.claudinite/local/usage.GENERATED.json';
49	export const FLEET_USAGE_PATH = 'usage-fleet.GENERATED.json';
50	export const FLEET_VERSION = 1;
51	
52	// The sampling population, stated in the file itself. This must not read as a
53	// census: a session whose container was reclaimed, or that crashed, never captured
54	// and is invisible to every number here.
55	export const SAMPLING_NOTE = 'Captured sessions only — sessions that merged, plus sessions that ended '
56	  + 'cleanly enough for the SessionEnd capture to fire. Reclaimed containers and crashes are invisible '
57	  + 'here, so these are SAMPLE counts, not a census of all work. The check counts are narrower still: '
58	  + 'they are what a session SAW. A CI run counts when the session pulled its job log in — which is '
59	  + 'what "the agent was in the loop on it" means — and a nightly or post-merge run nobody looked at '
60	  + 'does not, because nothing was corrected. CI can only see a run that PRINTED something, so its '
61	  + 'share is carried separately as ciRuns/ciFailures. Every check number is a floor on activations, '
62	  + 'never an over-count. The `tasks` rows are the ONE exception to all of the above: they come from '
63	  + "each member's scheduler run records rather than from a captured session, so they are a census of "
64	  + 'scheduled work — every due task of every run, whether or not any session was ever captured — '
65	  + 'bounded only by how far back that member has been folding them.';
66	
67	// --- the pure aggregation -----------------------------------------------------
68	
69	const sortKeys = (obj) => Object.fromEntries(Object.keys(obj).sort().map((k) => [k, obj[k]]));
70	
71	// Build the fleet file from `members` — `[{ repo, usage }]`, `usage` being that
72	// member's parsed aggregate — plus `absent`, the members that had none.
73	//
74	// GRAIN: full (week × repo × skill) for history, plus each member's current day
75	// window verbatim for the fast view. Nothing is pre-summed: every coarser view
76	// (a skill fleet-wide, a repo over time, this week across the fleet) stays derivable
77	// from this file, and a summary that threw away the grain would not.
78	export function aggregate({ members, absent = [], dormant = [], uncovered = [], outOfScope = [], generatedAt }) {
79	  const weeks = {};
80	  const days = {};
81	  const repos = {};
82	
83	  for (const { repo, usage } of members) {
84	    days[repo] = sortKeys(usage?.days ?? {});
85	    repos[repo] = {
86	      foldedThrough: usage?.foldedThrough ?? null,
87	      weeks: Object.keys(usage?.weeks ?? {}).length,
88	    };
89	    for (const [week, row] of Object.entries(usage?.weeks ?? {})) {
90	      ((weeks[week] ??= {})[repo] = {
91	        days: row.days ?? 0,
92	        captures: row.captures ?? 0,
93	        merges: row.merges ?? 0,
94	        sessionDays: row.sessionDays ?? 0,
95	        userMessages: row.userMessages ?? 0,
96	        userCommands: row.userCommands ?? 0,
97	        skillLoads: sortKeys(row.skillLoads ?? {}),
98	        // The conformance checks, at the same grain and for the same reason as the
99	        // skill loads: whether a rule earns its place is a FLEET question. A rule
100	        // that never fires in one repo may just not be that repo's subject; a rule
101	        // that never fires in ANY of them is mis-described or worthless — and a rule
102	        // that keeps firing everywhere is the corpus's best-performing guard, which
103	        // only a view across every member can tell apart. Defaulted, not required:
104	        // a member still on an older fold carries no `checks` key, and it must land
105	        // in the file as an empty row rather than an exception.
106	        checks: sortKeys(row.checks ?? {}),
107	        checkFindings: sortKeys(row.checkFindings ?? {}),
108	        // What each member's SCHEDULER did, per task: agent runs, deterministic
109	        // preprocessing-only runs, precondition skips, failures, deferrals. Carried
110	        // at the same week × repo × task grain and defaulted the same way, but drawn
111	        // from a different population and answering a different question — this is
112	        // the fleet's view of whether a scheduled task is doing anything at all. A
113	        // task that skips in every member every day is a precondition that never
114	        // fires; one that fails across members is broken machinery, not a bad night.
115	        tasks: sortKeys(row.tasks ?? {}),
116	      });
117	    }
118	  }
119	
120	  return {
121	    version: FLEET_VERSION,
122	    generatedAt,
123	    _note: SAMPLING_NOTE,
124	    coverage: {
125	      folding: Object.keys(repos).sort(),
126	      absent: [...absent].sort(),
127	      // Dormant members are OUT of the denominator, and named rather than dropped.
128	      // They are not an absence to chase — nobody is working there, so a skill that
129	      // never loads there says nothing about whether it earns its place — but a
130	      // reader comparing this file against the fleet's repo count needs to see where
131	      // the difference went. Absent means "should be folding and isn't"; dormant
132	      // means "not in the race at all".
133	      dormant: [...dormant].sort(),
134	      // The rest of the owner's repos, so the coverage section accounts for the WHOLE
135	      // fleet: uncovered repos (the census's subject — no member data to read) and
136	      // repos out of scope entirely (archived, forks, excluded — reason inline).
137	      // Neither contributes to any number; both are named so a reader can never
138	      // mistake "not a member" for "fell out of the file".
139	      uncovered: [...uncovered].sort(),
140	      outOfScope: [...outOfScope].sort(),
141	    },
142	    repos: sortKeys(repos),
143	    days: sortKeys(days),
144	    weeks: sortKeys(Object.fromEntries(Object.entries(weeks).map(([w, byRepo]) => [w, sortKeys(byRepo)]))),
145	  };
146	}
147	
148	// The folding members with NO captured activity on the day the file was generated —
149	// its day window carries no row for `generatedAt`. DERIVED from the file, not stored
150	// in it: the verdict moves when the date alone moves, and the worker's
151	// unchanged-compare deliberately ignores the day stamp so an unmoved fleet opens no
152	// PR — a stored copy would reopen that PR every midnight. The worker names them in
153	// the run report instead, where a daily fact belongs.
154	export function inactiveToday(file) {
155	  return file.coverage.folding.filter((repo) => !file.days[repo]?.[file.generatedAt]);
156	}
157	
158	// --- the fleet read -----------------------------------------------------------
159	
160	// One member's usage file at its default branch, or null when it has none. A
161	// non-200 that is not a 404, or an unparsable body, THROWS — the caller records it
162	// as an absence with a reason rather than treating "I could not read it" as "it has
163	// nothing".
164	async function readUsage(gh, fullName, path = MEMBER_USAGE_PATH) {
165	  const res = await gh(`/repos/${fullName}/contents/${path}`);
166	  if (res.status === 404) return null;
167	  if (res.status !== 200 || !res.json?.content) {
168	    throw new Error(`reading ${path} returned ${res.status}`);
169	  }
170	  try {
171	    return JSON.parse(Buffer.from(res.json.content, 'base64').toString('utf8'));
172	  } catch (e) {
173	    throw new Error(`unparsable ${path}: ${e.message}`);
174	  }
175	}
176	
177	// Exported so the fleet-usage task's worker can invoke the sweep in-process; the CLI
178	// guard below keeps the standalone run. Returns the built file — the worker owns
179	// delivering it, so this stays a pure "read the fleet, build the object" pass.
180	export async function main({ now = new Date() } = {}) {
181	  const token = process.env.FLEET_GITHUB_TOKEN;
182	  const home = process.env.GITHUB_REPOSITORY;
183	  if (!token) {
184	    throw new Error('FLEET_GITHUB_TOKEN is not set. Add a repo secret with a fine-grained PAT '
185	      + '(this account, ALL repositories, Metadata read, Contents read) — the default GITHUB_TOKEN '
186	      + 'sees only this repo and cannot read the fleet.');
187	  }
188	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
189	  const gh = makeGh(token);
190	
191	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
192	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
193	    throw new Error(`the sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
194	  }
195	  let cfg;
196	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
197	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
198	  }
199	  const { owner, exclude } = parseSheepdogConfig(cfg, home);
200	
201	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
202	    .filter((r) => r.owner.login.toLowerCase() === owner);
203	  if (mine.length === 0) {
204	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope; `
205	      + 'refusing to publish a fleet aggregate that would report the whole fleet as absent');
206	  }
207	
208	  const members = [];
209	  const absent = [];
210	  const dormant = [];
211	  const uncovered = [];
212	  const outOfScope = [];
213	  for (const r of mine.sort((a, b) => a.full_name.localeCompare(b.full_name))) {
214	    const fullName = r.full_name;
215	    const key = fullName.toLowerCase();
216	    // Not members, but not dropped either: the coverage section accounts for every
217	    // repo under the owner, and these land there with their reason.
218	    if (r.archived || r.fork) { outOfScope.push(`${fullName} (${r.archived ? 'archived' : 'fork'})`); continue; }
219	    if (exclude.has(key)) { outOfScope.push(`${fullName} (excluded)`); continue; }
220	    // Only COVERED repos are members. An uncovered repo is the census's subject, not
221	    // this sweep's — it is NAMED under coverage.uncovered, never counted as an absent
222	    // member, because "should be folding and isn't" is a different fact from "not a
223	    // member at all". The declaration is read rather than merely counted because
224	    // dormancy is inside it, and the same read answers both questions.
225	    let decl;
226	    try { decl = await readDeclaration(gh, fullName); } catch (e) {
227	      absent.push(`${fullName} (coverage check failed: ${e.message})`);
228	      continue;
229	    }
230	    if (decl === null) { uncovered.push(fullName); continue; }
231	    // A dormant member is out of the DENOMINATOR, not an absence: nobody is working
232	    // there, so "this skill never loaded" is a fact about the silence, not about the
233	    // skill, and averaging it in would drag every fleet-wide number toward zero as
234	    // the fleet accumulates finished projects.
235	    if (isDormant(decl)) { dormant.push(fullName); continue; }
236	    try {
237	      const usage = await readUsage(gh, fullName);
238	      if (usage === null) absent.push(`${fullName} (no ${MEMBER_USAGE_PATH} — not folding yet)`);
239	      else members.push({ repo: fullName, usage });
240	    } catch (e) {
241	      absent.push(`${fullName} (${e.message})`);
242	    }
243	  }
244	
245	  return aggregate({ members, absent, dormant, uncovered, outOfScope, generatedAt: now.toISOString().slice(0, 10) });
246	}
247	
248	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
249	if (isMain) {
250	  main()
251	    .then((file) => console.log(JSON.stringify(file, null, 2)))
