mkdir -p /tmp/claude-0/-home-user-Claudinite/432a0c70-de03-5907-beb1-2ef24784bb54/scratchpad && cat > /tmp/claude-0/-home-user-Claudinite/432a0c70-de03-5907-beb1-2ef24784bb54/scratchpad/proto.mjs <<'EOF'
import { readFileSync } from 'node:fs';
const u = JSON.parse(readFileSync('.claudinite/local/usage.GENERATED.json','utf8'));
const DAY=['captures','merges','sessions','userMessages','userCommands'];
const WEEK=['days','captures','merges','sessionDays','userMessages','userCommands'];
const CHECK=['runs','failures','errors','blocking','advisory','ciRuns','ciFailures'];
const FIND=['blocking','advisory'];
const TASK=['agent','prework','skipped','failed','deferred'];
const EXEC=['success','failed','task-gone','invalid'];
const tup=(row,fields)=>fields.map(f=>row?.[f]??0);
const mapTup=(m,fields)=>{const o={};for(const k of Object.keys(m??{}).sort())o[k]=tup(m[k],fields);return o;};
const group=(row,totalsFields)=>{
  const o={ totals: tup(row,totalsFields) };
  const add=(k,v)=>{ if(Object.keys(v).length) o[k]=v; };
  if(Object.keys(row.skillLoads??{}).length) o.skillLoads=row.skillLoads;
  add('checks',mapTup(row.checks,CHECK));
  add('checkFindings',mapTup(row.checkFindings,FIND));
  add('tasks',mapTup(row.tasks,TASK));
  add('taskExec',mapTup(row.taskExec,EXEC));
  return o;
};
const v2={version:2,foldedThrough:u.foldedThrough,runsFoldedThrough:u.runsFoldedThrough,
  fields:{day:DAY,week:WEEK,checks:CHECK,checkFindings:FIND,tasks:TASK,taskExec:EXEC},
  days:Object.fromEntries(Object.entries(u.days).map(([k,v])=>[k,group(v,DAY)])),
  weeks:Object.fromEntries(Object.entries(u.weeks).map(([k,v])=>[k,group(v,WEEK)]))};

// printer
function render(value, indent='', width=100){
  const flat=JSON.stringify(value);
  if(flat.length+indent.length<=width || typeof value!=='object' || value===null) return flat.replace(/,/g,', ').replace(/":/g,'": ');
  const inner=indent+'  ';
  if(Array.isArray(value)) return '[\n'+value.map(v=>inner+render(v,inner,width)).join(',\n')+'\n'+indent+']';
  const es=Object.entries(value);
  return '{\n'+es.map(([k,v])=>inner+JSON.stringify(k)+': '+render(v,inner,width)).join(',\n')+'\n'+indent+'}';
}
const out=render(v2)+'\n';
console.log('v1 pretty', readFileSync('.claudinite/local/usage.GENERATED.json','utf8').length);
console.log('v2 pretty2', JSON.stringify(v2,null,2).length);
console.log('v2 rows', out.length);
console.log(out.split('\n').slice(0,60).join('\n'));
EOF
