1	// The fleet-usage preprocessing entry point — the script the scheduler runs as
2	// `node worker.mjs` (cwd = this task dir, bounded by prework_timeout).
3	//
4	// It holds NO aggregation logic. The sweep is `aggregate-fleet-usage.mjs`, its
5	// SIBLING in this task folder — nothing outside this task uses it, so that is where
6	// it lives; this worker invokes it and DELIVERS its result. Same shape as the census
7	// and freshness workers, deliberately, with one difference: those two converge
8	// issues, and this one writes a file, so it carries the delivery step they don't.
9	//
10	// Two tokens, two jobs, and they are not interchangeable: the sweep READS the fleet
11	// over FLEET_GITHUB_TOKEN (the account-spanning PAT — the Action token sees only
12	// this repo), while the delivery WRITES this repo's own PR over the ordinary Action
13	// GITHUB_TOKEN.
14	//
15	// Failure is the escalation path. The sweep THROWS when its config or token is
16	// unusable, or when enumeration comes back empty; this worker turns that into a
17	// non-zero exit, and the scheduler treats a non-zero preprocessing subprocess as a
18	// failed task — it converges one open `needs-human` issue for the task family
19	// (engine/scheduler/run.mjs) instead of handing off to any agent.
20	
21	import { appendFileSync } from 'node:fs';
22	import { pathToFileURL } from 'node:url';
23	import { deliverGenerated, baseTip, readAt, remoteUrl } from '../../../../engine/scheduler/deliver-generated.mjs';
24	import { main as sweep, inactiveToday, FLEET_USAGE_PATH } from './aggregate-fleet-usage.mjs';
25	
26	const PR_BRANCH_PREFIX = 'claudinite/fleet-usage';
27	const slotId = process.env.CLAUDINITE_SLOT_ID || '';
28	const log = (s) => console.log(`fleet-usage${slotId ? ` [${slotId}]` : ''}: ${s}`);
29	
30	// `generatedAt` changes every day, so comparing the whole file would open a PR daily
31	// even on a fleet where nothing moved. Compare everything else: an unchanged fleet
32	// re-stamps nothing and opens nothing.
33	export function unchanged(priorText, nextText) {
34	  if (priorText === null) return false;
35	  const strip = (text) => {
36	    try { const { generatedAt, ...rest } = JSON.parse(text); return JSON.stringify(rest); } catch { return null; }
37	  };
38	  const prior = strip(priorText);
39	  return prior !== null && prior === strip(nextText);
40	}
41	
42	// The run report — the FULL fleet roster, every repo named under exactly one state,
43	// emitted on every run (the PR only opens when the fleet moved, and a fleet that
44	// did not move still deserves an account of itself — including who was inactive
45	// today, a daily fact that deliberately lives here and not in the file, because
46	// `unchanged` above ignores the day stamp). Pure so the full-roster property is
47	// testable directly.
48	export function renderUsageSummary(file) {
49	  const { folding, absent, dormant, uncovered, outOfScope } = file.coverage;
50	  const quiet = inactiveToday(file);
51	  const quietSet = new Set(quiet);
52	  const active = folding.filter((r) => !quietSet.has(r));
53	  return [
54	    `# Fleet usage sweep — ${file.generatedAt}`,
55	    '',
56	    '| folding | inactive today | absent | dormant | uncovered | out of scope |',
57	    '| --- | --- | --- | --- | --- | --- |',
58	    `| ${folding.length} | ${quiet.length} | ${absent.length} | ${dormant.length} | ${uncovered.length} | ${outOfScope.length} |`,
59	    '',
60	    active.length ? `**Folding, active today:** ${active.join(', ')}` : '**Folding, active today:** none',
61	    quiet.length ? `**Folding, inactive today (no captured activity on ${file.generatedAt}):** ${quiet.join(', ')}` : '',
62	    absent.length ? `**Absent (should be folding and isn't):** ${absent.join('; ')}` : '',
63	    dormant.length ? `**Dormant (self-declared, out of the denominator):** ${dormant.join(', ')}` : '',
64	    uncovered.length ? `**Uncovered (the census's subject):** ${uncovered.join(', ')}` : '',
65	    outOfScope.length ? `**Out of scope:** ${outOfScope.join(', ')}` : '',
66	  ].filter(Boolean).join('\n');
67	}
68	
69	export async function main() {
70	  // The sweep resolves the HOME repo — the one whose sheepdog pack entry carries the
71	  // fleet config, and the one the aggregate lands in — from GITHUB_REPOSITORY.
72	  // Actions sets it and the subprocess inherits it; CLAUDINITE_REPO is the
73	  // scheduler's own name for the same fact, so fall back to it rather than depending
74	  // on which of the two happens to be present.
75	  if (!process.env.GITHUB_REPOSITORY && process.env.CLAUDINITE_REPO) {
76	    process.env.GITHUB_REPOSITORY = process.env.CLAUDINITE_REPO;
77	  }
78	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
79	  const repo = process.env.GITHUB_REPOSITORY;
80	  const token = process.env.GITHUB_TOKEN;
81	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
82	  if (!token) throw new Error('GITHUB_TOKEN is not set — the sweep cannot deliver its aggregate');
83	
84	  log('reading every member\'s usage aggregate');
85	  const file = await sweep();
86	  const text = `${JSON.stringify(file, null, 2)}\n`;
87	  const covered = file.coverage.folding.length;
88	  const gaps = file.coverage.absent.length;
89	
90	  const summary = renderUsageSummary(file);
91	  console.log(summary);
92	  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${summary}\n`);
93	
94	  const baseSha = baseTip(root, remoteUrl(repo, token), base);
95	  if (unchanged(readAt(root, baseSha, FLEET_USAGE_PATH), text)) {
96	    log(`${covered} member(s) folding, ${gaps} coverage gap(s) — recompute is unchanged, nothing to deliver`);
97	    return;
98	  }
99	
100	  const today = new Date().toISOString().slice(0, 10);
101	  const pr = await deliverGenerated({
102	    root, repo, base, token, stamp: today, branchPrefix: PR_BRANCH_PREFIX, log,
103	    files: { [FLEET_USAGE_PATH]: text },
104	    message: 'Claudinite: recompute the fleet skill-usage aggregate',
105	    title: 'Claudinite: fleet skill-usage aggregate',
106	    body: [
107	      `Recomputed \`${FLEET_USAGE_PATH}\` from the fleet members' own usage aggregates.`,
108	      '',
109	      `**${covered}** member(s) folding (**${inactiveToday(file).length}** of them inactive today); `
110	        + `**${gaps}** coverage gap(s) under \`coverage.absent\`; **${file.coverage.dormant.length}** dormant, `
111	        + `**${file.coverage.uncovered.length}** uncovered and **${file.coverage.outOfScope.length}** out-of-scope `
112	        + 'repo(s) named under `coverage` — the file accounts for every repo under the owner.',
113	      '',
114	      'A stateless full recompute: this file is a pure function of the members\' current',
115	      'files, so it self-heals any past error and an unchanged fleet opens no PR.',
116	      'Machine-written — never hand-edit it.',
117	    ].join('\n'),
118	  });
119	  log(`${covered} member(s) folding, ${gaps} coverage gap(s) — ${pr.reused ? 'updated' : 'opened'} `
120	    + `PR ${pr.number !== null ? `#${pr.number}` : `on ${pr.branch}`}`
121	    + `${pr.merged ? ' (landed)' : pr.delivery === 'review' ? ' (left for review)' : ''}`);
122	}
123	
124	// Run only when invoked directly (the scheduler's `node worker.mjs`), never on import.
125	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
126	  main().catch((e) => { console.error(`fleet-usage failed: ${e.message}`); process.exit(1); });
