// Render `value` as JSON text with no trailing newline. `width` is the budget for a
// line INCLUDING its indent; a container wider than that is expanded one child per
// line and each child re-measured against the same budget.
export function renderJson(value, { width = 100, indent = '' } = {}) {
  const flat = inline(value);
  if (value === null || typeof value !== 'object' || indent.length + flat.length <= width) return flat;
  const inner = `${indent}  `;
  const children = Array.isArray(value)
    ? value.map((v) => `${inner}${renderJson(v, { width, indent: inner })}`)
    : entries(value).map(([k, v]) => `${inner}${JSON.stringify(k)}: ${renderJson(v, { width, indent: inner })}`);

