1	// Deliver GENERATED files on a pull request that lands itself — the write half of
2	// an agentless task whose whole output is a regenerated file.
3	//
4	// It exists because two tasks need exactly this and must not each grow their own
5	// copy: the per-repo skill-usage fold and the sheepdog's fleet aggregate both
6	// recompute a `*.GENERATED.json` from scratch and want it landed without a human in
7	// the loop. (the update runner's own delivery is deliberately NOT folded in here: it
8	// commits a whole working tree and re-cuts a dated family branch each cycle — a
9	// different job that happens to end in a PR too. What the two DO share — every
10	// nuance of actually landing the PR under the member's `maintenance.delivery` and
11	// the repo's own shape — lives in land-pr.mjs, and both call it.)
12	//
13	// Two properties everything here is shaped around:
14	//
15	//   NOTHING TOUCHES THE CHECKOUT. The scheduler runs every due task in ONE checkout,
16	//   so a task that checks a branch out hands the next task a tree it did not expect.
17	//   Every write goes through git plumbing (hash-object / read-tree into a throwaway
18	//   index / write-tree / commit-tree / push), against the fetched base tip — HEAD,
19	//   the index and the working tree are never touched, and there is nothing to clean
20	//   up if the run dies.
21	//
22	//   THE BASE IS THE ONLY AUTHORITY. Both the prior state a generator reads and the
23	//   tree it builds on come from the remote base branch, never from local HEAD. A
24	//   previous run's PR still sitting open is simply rebuilt from the base, so a
25	//   stateless generator stays idempotent no matter how many runs stack up. The
26	//   member's delivery preference is read from the base too, for the same reason.
27	//
28	// Idempotence is the caller's to keep: pass files whose content is a pure function of
29	// the inputs, and compare against `readAtBase` before calling — an identical
30	// recompute should open nothing at all.
31	
32	import { execFileSync } from 'node:child_process';
33	import { rmSync } from 'node:fs';
34	import { tmpdir } from 'node:os';
35	import { join } from 'node:path';
36	import { deliveryFromChecks, pullCreateError, landDelivery } from './land-pr.mjs';
37	
38	const API = 'https://api.github.com';
39	
40	const git = (root, args, opts = {}) => execFileSync('git', ['-C', root, ...args], {
41	  encoding: 'utf8',
42	  // A generated file can be large, and a `git show` of one easily tops spawn's
43	  // default 1 MiB buffer — which fails as a truncated read, not as an error.
44	  maxBuffer: 256 * 1024 * 1024,
45	  // stdin is 'pipe' exactly when there is input to pipe: an explicit 'ignore' with an
46	  // `input` set silently feeds the child NOTHING, and `hash-object --stdin` then
47	  // cheerfully writes the empty blob — a wrong answer, not an error.
48	  stdio: [opts.input === undefined ? 'ignore' : 'pipe', 'pipe', 'pipe'],
49	  ...opts,
50	});
51	
52	async function gh(token, path, { method = 'GET', body } = {}) {
53	  const res = await fetch(`${API}${path}`, {
54	    method,
55	    headers: {
56	      authorization: `Bearer ${token}`,
57	      accept: 'application/vnd.github+json',
58	      'x-github-api-version': '2022-11-28',
59	      ...(body ? { 'content-type': 'application/json' } : {}),
60	    },
61	    body: body ? JSON.stringify(body) : undefined,
62	  });
63	  let json = null;
64	  try { json = await res.json(); } catch { /* empty body */ }
65	  return { status: res.status, json };
66	}
67	
68	export const remoteUrl = (repo, token) => `https://x-access-token:${token}@github.com/${repo}.git`;
69	
70	// The base branch's remote tip, fetched into this checkout's object store. Read from
71	// the REMOTE, never from HEAD — see the header.
72	export function baseTip(root, remote, base) {
73	  git(root, ['fetch', '--quiet', remote, base]);
74	  return git(root, ['rev-parse', 'FETCH_HEAD']).trim();
75	}
76	
77	// One file's content at a commit, or null when the path does not exist there.
78	export function readAt(root, sha, path) {
79	  try { return git(root, ['show', `${sha}:${path}`]); } catch { return null; }
80	}
81	
82	// Commit `files` ({ path: content }) onto the base tip and push to `branch`,
83	// force — the content is regenerated wholesale each run, so the branch is a
84	// regenerate-not-reconcile surface.
85	export function pushGenerated(root, { remote, baseSha, branch, files, message }) {
86	  const index = join(tmpdir(), `claudinite-deliver-${process.pid}-${Date.now()}.index`);
87	  const plumb = (args, opts) => git(root, args, { ...opts, env: { ...process.env, GIT_INDEX_FILE: index } });
88	  try {
